163	  public createWindow(): void {
164	    if (this.launcherWindow !== null) return // Already created
165	
166	    const primaryDisplay = screen.getPrimaryDisplay()
167	    const workArea = primaryDisplay.workArea
168	
169	    // Fixed dimensions per user request
170	    const width = 1200;
171	    const height = 800;
172	
173	    // Calculate centered X, and top-centered Y (5% from top)
174	    const x = Math.round(workArea.x + (workArea.width - width) / 2);
175	    // Ensure y is at least workArea.y (don't go offscreen top)
176	    const topMargin = Math.round(workArea.height * 0.05);
177	    const y = Math.round(workArea.y + topMargin);
178	
179	    // --- 1. Create Launcher Window ---
180	    const isMac = process.platform === "darwin";
181	
182	    const launcherSettings: Electron.BrowserWindowConstructorOptions = {
183	      width: width,
184	      height: height,
185	      x: x,
186	      y: y,
187	      minWidth: 600,
188	      minHeight: 400,
189	      webPreferences: {
190	        nodeIntegration: false,
191	        contextIsolation: true,
192	        preload: path.join(__dirname, "preload.js"),
193	        scrollBounce: true,
194	        webSecurity: !isDev, // DEBUG: Disable web security only in dev
195	      },
196	      show: false, // DEBUG: Force show -> Fixed white screen, now relies on ready-to-show
197	      // Platform-specific frame settings
198	      ...(isMac
199	        ? { titleBarStyle: 'hiddenInset' as const, trafficLightPosition: { x: 14, y: 14 } }
200	        : { frame: false, titleBarOverlay: false, autoHideMenuBar: true }),
201	      // Launcher must be opaque on macOS — layer-backed transparent NSWindows
202	      // (transparent:true / vibrancy) are not covered by NSWindowSharingNone,
203	      // so setContentProtection silently fails to hide them from
204	      // ScreenCaptureKit. Solid window = working screen-share protection.
205	      transparent: false,
206	      hasShadow: true,
207	      // Opaque alpha required on macOS — an alpha-0 backgroundColor leaves
208	      // the NSWindow in a layer-backed transparent state that
209	      // NSWindowSharingNone does not cover.
210	      backgroundColor: "#000000",
211	      focusable: true,
212	      resizable: true,
213	      movable: true,
214	      center: true,
215	      icon: (() => {
216	        const isMac = process.platform === "darwin";
217	        const isWin = process.platform === "win32";
218	        const mode = this.appState.getDisguise();
219	
220	        if (mode === 'none') {
221	          if (isMac) {
222	            return app.isPackaged
223	              ? path.join(process.resourcesPath, "natively.icns")
224	              : path.resolve(__dirname, "../../assets/natively.icns");
225	          } else if (isWin) {
226	            return app.isPackaged
227	              ? path.join(process.resourcesPath, "assets/icons/win/icon.ico")
228	              : path.resolve(__dirname, "../../assets/icons/win/icon.ico");
229	          } else {
230	            return app.isPackaged
231	              ? path.join(process.resourcesPath, "icon.png")
232	              : path.resolve(__dirname, "../../assets/icon.png");
233	          }
234	        }
235	
236	        // Disguise mode icons
237	        let iconName = "terminal.png";
238	        if (mode === 'settings') iconName = "settings.png";
239	        if (mode === 'activity') iconName = "activity.png";
240	
241	        const platformDir = isWin ? "win" : "mac";
242	        return app.isPackaged
243	          ? path.join(process.resourcesPath, `assets/fakeicon/${platformDir}/${iconName}`)
244	          : path.resolve(__dirname, `../../assets/fakeicon/${platformDir}/${iconName}`);
245	      })()
246	    }
247	
248	    console.log(`[WindowHelper] Icon Path: ${launcherSettings.icon}`);
249	    console.log(`[WindowHelper] Start URL: ${startUrl}`);
250	
251	    try {
252	      this.launcherWindow = new BrowserWindow(launcherSettings)
253	      console.log('[WindowHelper] BrowserWindow created successfully');
254	    } catch (err) {
255	      console.error('[WindowHelper] Failed to create BrowserWindow:', err);
256	      return;
257	    }
258	
259	    this.launcherWindow.setContentProtection(this.contentProtection)
260	    console.log(`[WindowHelper] launcher created with setContentProtection(${this.contentProtection})`)
261	
262	    this.launcherWindow.once('ready-to-show', () => {
263	      if (this.launcherWindow && !this.launcherWindow.isDestroyed()) {
264	        this.launcherWindow.setContentProtection(this.contentProtection)
265	        console.log(`[WindowHelper] launcher ready-to-show: re-applied setContentProtection(${this.contentProtection})`)
266	      }
267	    })
268	
269	    this.launcherWindow.loadURL(`${startUrl}?window=launcher`)
270	      .then(() => console.log('[WindowHelper] loadURL success'))
271	      .catch((e) => { console.error("[WindowHelper] Failed to load URL:", e) })
272	
273	    this.launcherWindow.webContents.on('did-fail-load', (event, errorCode, errorDescription) => {
274	      console.error(`[WindowHelper] did-fail-load: ${errorCode} ${errorDescription}`);
275	    });
276	
277	    // if (isDev) {
278	    //   this.launcherWindow.webContents.openDevTools({ mode: 'detach' }); // DEBUG: Open DevTools
279	    // }
