281	    // --- 2. Create Overlay Window (Hidden initially) ---
282	    // Always start centered on the primary display so the OS (macOS NSUserDefaults /
283	    // Windows DWM) cannot restore the previous session's cached window position.
284	    // The in-memory `overlayBounds` is already null here, so `switchToOverlay()`
285	    // will also fall back to centered logic — but providing explicit x/y in the
286	    // constructor is the only reliable guard against OS-level position persistence.
287	    const overlayDefaultX = Math.floor(workArea.x + (workArea.width - WindowHelper.OVERLAY_DEFAULT_WIDTH) / 2);
288	    const overlayDefaultY = Math.floor(workArea.y + workArea.height * WindowHelper.OVERLAY_DEFAULT_TOP_RATIO);
289	
290	    const overlaySettings: Electron.BrowserWindowConstructorOptions = {
291	      width: WindowHelper.OVERLAY_DEFAULT_WIDTH,
292	      height: 1,
293	      x: overlayDefaultX,
294	      y: overlayDefaultY,
295	      minWidth: 300,
296	      minHeight: 1,
297	      webPreferences: {
298	        nodeIntegration: false,
299	        contextIsolation: true,
300	        preload: path.join(__dirname, "preload.js"),
301	        scrollBounce: true,
302	      },
303	      show: false,
304	      frame: false, // Frameless
305	      transparent: true,
306	      backgroundColor: "#00000000",
307	      alwaysOnTop: true,
308	      focusable: true,
309	      resizable: false, // Enforce automatic resizing only
310	      movable: true,
311	      skipTaskbar: true, // Don't show separately in dock/taskbar
312	      hasShadow: false, // Prevent shadow from adding perceived size/artifacts
313	    }
314	
315	    this.overlayWindow = new BrowserWindow(overlaySettings)
316	    this.overlayWindow.setContentProtection(this.contentProtection)
317	
318	    if (process.platform === "darwin") {
319	      this.overlayWindow.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true })
320	      this.overlayWindow.setHiddenInMissionControl(true)
321	      this.overlayWindow.setAlwaysOnTop(true, "floating")
322	    } else if (process.platform === "win32") {
323	      // 'floating' level (HWND_TOPMOST baseline) is not enough to render above
324	      // fullscreen browser windows (F11). 'screen-saver' uses a higher TOPMOST
325	      // priority that wins against window-mode fullscreen apps. macOS uses
326	      // visibleOnFullScreen above; Windows has no equivalent flag, so the level
327	      // itself is what controls fullscreen visibility. See issue #167.
328	      this.overlayWindow.setAlwaysOnTop(true, "screen-saver")
329	    }
330	
331	    this.overlayWindow.loadURL(`${startUrl}?window=overlay`).catch(e => {
332	        console.error('[WindowHelper] Failed to load Overlay URL:', e);
333	    })
334	
335	    // --- 3. Startup Sequence ---
336	    this.launcherWindow.once('ready-to-show', () => {
337	      this.switchToLauncher()
338	      this.isWindowVisible = true
339	    })
340	
341	    this.setupWindowListeners()
342	  }
