344	  private setupWindowListeners(): void {
345	    if (!this.launcherWindow) return
346	
347	    // Suppress Windows system context menu on right-click (title bar)
348	    this.launcherWindow.on('system-context-menu', (e, point) => {
349	      e.preventDefault();
350	      if (!this.appState.getUndetectable()) {
351	        this.showContextMenu(this.launcherWindow!, point);
352	      }
353	    });
354	
355	    this.launcherWindow.on("move", () => {
356	      if (this.launcherWindow) {
357	        const bounds = this.launcherWindow.getBounds()
358	        this.launcherPosition = { x: bounds.x, y: bounds.y }
359	        this.appState.settingsWindowHelper.reposition(bounds)
360	      }
361	    })
362	
363	    this.launcherWindow.on("resize", () => {
364	      if (this.launcherWindow) {
365	        const bounds = this.launcherWindow.getBounds()
366	        this.launcherSize = { width: bounds.width, height: bounds.height }
367	        this.appState.settingsWindowHelper.reposition(bounds)
368	      }
369	    })
370	
371	    // On Windows/Linux: intercept close and hide to tray instead of quitting,
372	    // unless the app is actually quitting (e.g. from tray "Quit" menu).
373	    if (process.platform !== 'darwin') {
374	      this.launcherWindow.on('close', (e) => {
375	        if (!this.appState.isQuitting()) {
376	          e.preventDefault();
377	          this.launcherWindow?.hide();
378	          this.isWindowVisible = false;
379	        }
380	      });
381	
382	      // Sync maximize state to renderer so WindowControls stays in sync (Windows/Linux only)
383	      this.launcherWindow.on('maximize', () => {
384	        this.launcherWindow?.webContents.send('window-maximized-changed', true);
385	      });
386	      this.launcherWindow.on('unmaximize', () => {
387	        this.launcherWindow?.webContents.send('window-maximized-changed', false);
388	      });
389	    }
390	
391	    this.launcherWindow.on("closed", () => {
392	      this.launcherWindow = null
393	      // If launcher closes, we should probably quit app or close overlay
394	      if (this.overlayWindow && !this.overlayWindow.isDestroyed()) {
395	        this.overlayWindow.close()
396	      }
397	      this.overlayWindow = null
398	      this.isWindowVisible = false
399	    })
400	
401	    // Listen for overlay close (e.g. Cmd+W). Never truly destroy it — either
402	    // hide it (during a meeting) or switch back to launcher (between meetings).
403	    if (this.overlayWindow) {
404	      this.overlayWindow.on("move", () => {
405	        if (this.overlayWindow && !this.overlayWindow.isDestroyed()) {
406	          this.overlayBounds = this.overlayWindow.getBounds()
407	        }
408	      })
409	
410	      this.overlayWindow.on("resize", () => {
411	        if (this.overlayWindow && !this.overlayWindow.isDestroyed()) {
412	          this.overlayBounds = this.overlayWindow.getBounds()
413	        }
414	      })
415	
416	      this.overlayWindow.on('system-context-menu', (e, point) => {
417	        e.preventDefault();
418	        if (!this.appState.getUndetectable()) {
419	          this.showContextMenu(this.overlayWindow!, point);
420	        }
421	      });
422	
423	      // Re-assert always-on-top on blur (Windows only). Screen-sharing tools
424	      // (Zoom, Lark, Teams, etc.) hook the DWM compositor and can demote even
425	      // HWND_TOPMOST windows below their shared content layer. Re-applying the
426	      // 'screen-saver' level on every blur keeps the overlay above the share
427	      // surface. Skipped on macOS — re-asserting setAlwaysOnTop there triggers
428	      // [NSApp activate], which steals focus from the underlying app. See #130.
429	      if (process.platform === 'win32') {
430	        this.overlayWindow.on('blur', () => {
431	          if (!this.overlayWindow || this.overlayWindow.isDestroyed()) return;
432	          if (!this.overlayWindow.isVisible()) return;
433	          this.overlayWindow.setAlwaysOnTop(true, 'screen-saver');
434	        });
435	      }
436	
437	      this.overlayWindow.on('close', (e) => {
438	        if (this.overlayWindow?.isVisible()) {
439	          e.preventDefault();
440	          if (this.appState.getIsMeetingActive()) {
441	            // Meeting running — just hide the overlay; user can resume from the
442	            // launcher's "Meeting ongoing" button which calls setWindowMode('overlay').
443	            this.hideOverlay();
444	          } else {
445	            this.switchToLauncher();
446	          }
447	        }
448	      })
449	    }
450	  }
