504	  // Apply or remove click-through (mouse passthrough) on the overlay window.
505	  // Called whenever the passthrough state changes in AppState.
506	  public syncOverlayInteractionPolicy(): void {
507	    if (!this.overlayWindow || this.overlayWindow.isDestroyed()) return;
508	
509	    const passthrough = this.appState.getOverlayMousePassthrough();
510	    if (passthrough) {
511	      // forward: true — pointer events are still delivered to the OS layer beneath.
512	      // NOTE: We intentionally do NOT call setFocusable(false) here.
513	      //
514	      // Rationale: setIgnoreMouseEvents() alone is sufficient for transparent
515	      // mouse behaviour.  Setting focusable=false when the overlay is the only
516	      // visible window makes macOS treat the app as having NO active windows.
517	      // In that state, macOS may stop delivering Carbon/IOKit global hotkey
518	      // events to the process — silently breaking every globalShortcut binding.
519	      // Keeping the window focusable costs nothing: in passthrough mode the
520	      // user is in another app and will not accidentally focus the overlay.
521	      this.overlayWindow.setIgnoreMouseEvents(true, { forward: true });
522	      console.log('[WindowHelper] Overlay mouse passthrough ON');
523	    } else {
524	      this.overlayWindow.setIgnoreMouseEvents(false);
525	      // Restore full interactivity when passthrough is turned off.
526	      this.overlayWindow.setFocusable(true);
527	      console.log('[WindowHelper] Overlay mouse passthrough OFF');
528	    }
529	  }
