531	  // Show overlay directly without going through full switchToOverlay flow.
532	  // Used by IPC handlers to show the overlay independently.
533	  public showOverlay(): void {
534	    if (!this.overlayWindow || this.overlayWindow.isDestroyed()) return;
535	
536	    // Restore opacity in case it was zeroed by hideMainWindow() before a screenshot.
537	    this.overlayWindow.setOpacity(1);
538	
